import org.apache.flink.streaming.api.windowing.time.Time;
import org.apache.flink.core.fs.FileSystem;
import org.apache.flink.api.common.functions.FilterFunction;

import java.time.Duration;
import java.util.HashSet;
import java.util.Set;

public class LongestSessionPerJob extends AppBase {

    public static void main(String[] args) throws Exception {

        ParameterTool params = ParameterTool.fromArgs(args);
        String taskInput = params.get("task_input", null);
        String jobInput = params.get("job_input", null);
        String outputPath = params.get("output", null);
        System.out.println("task_input  " + taskInput);
        System.out.println("job_input  " + jobInput);
        final int sesssize = params.getInt("sesssize", 600);

        // set up streaming execution environment
        StreamExecutionEnvironment env = StreamExecutionEnvironment.getExecutionEnvironment();

        // Create FileSource for task events
        FileSource<String> taskFileSource = FileSource
                .forRecordStreamFormat(new TextLineInputFormat(), new Path(taskInput))
                .build();

        // Create FileSource for job events
        FileSource<String> jobFileSource = FileSource
                .forRecordStreamFormat(new TextLineInputFormat(), new Path(jobInput))
                .build();

        // Read and parse task events
        DataStream<TaskEvent> taskEvents = env
                .fromSource(taskFileSource, WatermarkStrategy.noWatermarks(), "Task Events Source")
                .map(new MapFunction<String, TaskEvent>() {
                    @Override
                    public TaskEvent map(String line) throws Exception {
                        String[] fields = line.split(",", -1);
                        TaskEvent event = new TaskEvent();
                        event.setTimestamp(Long.parseLong(fields[0]));
                        event.setMissingInfo(fields[1]);
                        event.setJobId(Long.parseLong(fields[2]));
                        event.setTaskIndex(Long.parseLong(fields[3]));
                        if (!fields[4].isEmpty()) {
                            event.setMachineId(Long.parseLong(fields[4]));
                        }
                        event.setEventType(Integer.parseInt(fields[5]));
                        event.setUser(fields[6]);
                        event.setSchedulingClass(Integer.parseInt(fields[7]));
                        event.setPriority(Integer.parseInt(fields[8]));
                        event.setCpuRequest(Double.parseDouble(fields[9]));
                        event.setMemoryRequest(Double.parseDouble(fields[10]));
                        event.setDiskSpaceRequest(Double.parseDouble(fields[11]));
                        event.setDifferentMachinesRestriction(Integer.parseInt(fields[12]));
                        return event;
                    }
                });

        // Read and parse job events
        DataStream<JobEvent> jobEvents = env
                .fromSource(jobFileSource, WatermarkStrategy.noWatermarks(), "Job Events Source")
                .map(new MapFunction<String, JobEvent>() {
                    @Override
                    public JobEvent map(String line) throws Exception {
                        String[] fields = line.split(",", -1);
                        JobEvent event = new JobEvent();
                        event.setTimestamp(Long.parseLong(fields[0]));
                        event.setMissingInfo(fields[1]);
                        event.setJobId(Long.parseLong(fields[2]));
                        event.setEventType(Integer.parseInt(fields[3]));
                        event.setUser(fields[4]);
                        event.setSchedulingClass(Integer.parseInt(fields[5]));
                        event.setJobName(fields[6]);
                        event.setLogicalJobName(fields[7]);
                        return event;
                    }
                });

        // Get finished jobs - jobs with FINISH event (eventType = 4)
        DataStream<Long> finishedJobs = jobEvents
                .filter(new FilterFunction<JobEvent>() {
                    @Override
                    public boolean filter(JobEvent event) throws Exception {
                        return event.getEventType() == JobEvent.FINISH;
                    }
                })
                .map(new MapFunction<JobEvent, Long>() {
                    @Override
                    public Long map(JobEvent event) throws Exception {
                        return event.getJobId();
                    }
                })
                .keyBy(jobId -> jobId)
                .reduce(new ReduceFunction<Long>() {
                    @Override
                    public Long reduce(Long value1, Long value2) throws Exception {
                        return value1; // Just keep one
                    }
                });

        // Filter only SUBMIT events (eventType = 0)
        DataStream<TaskEvent> submitEvents = taskEvents
                .filter(new FilterFunction<TaskEvent>() {
                    @Override
                    public boolean filter(TaskEvent event) throws Exception {
                        return event.getEventType() == TaskEvent.SUBMIT;
                    }
                });

        // Assign timestamps and watermarks for event time processing
        DataStream<TaskEvent> submitEventsWithTimestamps = submitEvents
                .assignTimestampsAndWatermarks(
                        WatermarkStrategy.<TaskEvent>forBoundedOutOfOrderness(Duration.ofSeconds(0))
                                .withTimestampAssigner(new SerializableTimestampAssigner<TaskEvent>() {
                                    @Override
                                    public long extractTimestamp(TaskEvent element, long recordTimestamp) {
                                        // Convert microseconds to milliseconds
                                        return element.getTimestamp() / 1000;
                                    }
                                })
                );

        // Group by jobId and apply session windows (10 minutes = 600 seconds gap)
        // Count tasks in each session
        DataStream<Tuple3<Long, Long, Long>> sessionCounts = submitEventsWithTimestamps
                .keyBy(TaskEvent::getJobId)
                .window(EventTimeSessionWindows.withGap(Time.seconds(sesssize)))
                .apply(new org.apache.flink.streaming.api.functions.windowing.WindowFunction<
                        TaskEvent, Tuple3<Long, Long, Long>, Long, org.apache.flink.streaming.api.windowing.windows.TimeWindow>() {
                    @Override
                    public void apply(Long jobId,
                                    org.apache.flink.streaming.api.windowing.windows.TimeWindow window,
                                    Iterable<TaskEvent> input,
                                    org.apache.flink.util.Collector<Tuple3<Long, Long, Long>> out) throws Exception {
                        long count = 0;
                        for (TaskEvent event : input) {
                            count++;
                        }
                        // Emit (jobId, sessionStart, count)
                        out.collect(new Tuple3<>(jobId, window.getStart(), count));
                    }
                });

        // Find the session with maximum count for each job
        DataStream<Tuple2<Long, Long>> longestSessions = sessionCounts
                .keyBy(tuple -> tuple.f0) // Key by jobId
                .reduce(new ReduceFunction<Tuple3<Long, Long, Long>>() {
                    @Override
                    public Tuple3<Long, Long, Long> reduce(Tuple3<Long, Long, Long> value1,
                                                            Tuple3<Long, Long, Long> value2) throws Exception {
                        // Keep the session with more tasks
                        if (value1.f2 > value2.f2) {
                            return value1;
                        } else if (value1.f2 < value2.f2) {
                            return value2;
                        } else {
                            // If equal, keep the earlier one
                            return value1.f1 < value2.f1 ? value1 : value2;
                        }
                    }
                })
                .map(new MapFunction<Tuple3<Long, Long, Long>, Tuple2<Long, Long>>() {
                    @Override
                    public Tuple2<Long, Long> map(Tuple3<Long, Long, Long> value) throws Exception {
                        return new Tuple2<>(value.f0, value.f2); // (jobId, maxCount)
                    }
                });

        // Join with finished jobs to only output results for finished jobs
        DataStream<String> result = longestSessions
                .join(finishedJobs)
                .where(tuple -> tuple.f0) // jobId from longestSessions
                .equalTo(jobId -> jobId)  // jobId from finishedJobs
                .window(org.apache.flink.streaming.api.windowing.assigners.TumblingProcessingTimeWindows.of(Time.hours(24)))
                .apply(new org.apache.flink.streaming.api.functions.co.JoinFunction<Tuple2<Long, Long>, Long, String>() {
                    @Override
                    public String join(Tuple2<Long, Long> sessionInfo, Long finishedJobId) throws Exception {
                        return "(" + sessionInfo.f0 + "," + sessionInfo.f1 + ")";
                    }
                });

        // Write output to file
        result.writeAsText(outputPath, FileSystem.WriteMode.OVERWRITE)
                .setParallelism(1);

        env.execute("LongestSessionPerJob");
    }

}

