                        event.setTaskIndex(Long.parseLong(fields[3]));
                        if (!fields[4].isEmpty()) {
                            event.setMachineId(Long.parseLong(fields[4]));
                        }
                        event.setEventType(Integer.parseInt(fields[5]));
                        event.setUser(fields[6]);
                        event.setSchedulingClass(Integer.parseInt(fields[7]));
                        event.setPriority(Integer.parseInt(fields[8]));
                        event.setCpuRequest(Double.parseDouble(fields[9]));
                        event.setMemoryRequest(Double.parseDouble(fields[10]));
                        event.setDiskSpaceRequest(Double.parseDouble(fields[11]));
                        event.setDifferentMachinesRestriction(Integer.parseInt(fields[12]));
                        return event;
                    }
                });

        // Read and parse job events
        DataStream<JobEvent> jobEvents = env
                .fromSource(jobFileSource, WatermarkStrategy.noWatermarks(), "Job Events Source")
                .map(new MapFunction<String, JobEvent>() {
                    @Override
                    public JobEvent map(String line) throws Exception {
                        String[] fields = line.split(",", -1);
                        JobEvent event = new JobEvent();
                        event.setTimestamp(Long.parseLong(fields[0]));
                        event.setMissingInfo(fields[1]);
                        event.setJobId(Long.parseLong(fields[2]));
                        event.setEventType(Integer.parseInt(fields[3]));
                        event.setUser(fields[4]);
                        event.setSchedulingClass(Integer.parseInt(fields[5]));
                        event.setJobName(fields[6]);
                        event.setLogicalJobName(fields[7]);
                        return event;
                    }
                });

        // Get finished jobs - jobs with FINISH event (eventType = 4)
        DataStream<Long> finishedJobs = jobEvents
                .filter(new FilterFunction<JobEvent>() {
                    @Override
                    public boolean filter(JobEvent event) throws Exception {
